import itertools
from collections import UserList

from robot import version
from robot.errors import DataError
from robot.result import Message

ROBOT_VERSION = tuple(map(int, version.get_version().split(".")))
SETUP_OR_TEARDOWN_KW_TYPES = ("setup", "teardown", "SETUP", "TEARDOWN")


if ROBOT_VERSION < (3, 2):
    from robot.api import TestData
    from robot.result.model import TestCase

else:
    from robot.parsing import ModelVisitor, get_model

    def flatten(it):
        return itertools.chain.from_iterable(it)

    class SettingTable:
        def __init__(self):
            self.test_tags = []
            self.default_tags = []  # deprecated
            self.force_tags = []  # deprecated

    class TestCase:
        __test__ = False

        def __init__(self):
            self.name = ""
            self.tags = []

    class TestCaseTable(UserList):
        __test__ = False
        pass

    class TestData(ModelVisitor):
        __test__ = False

        def __init__(self, source=None):
            self.testcase_table = TestCaseTable()
            self.setting_table = SettingTable()
            model = get_model(source)
            if model:
                self.visit(model)
                if self.testcase_table:
                    return
            raise DataError()

        def visit_ForceTags(self, node):
            """
            Since RF 5.1 Test Tag is and alias for Force Tags.
            In RF 6.0 Force Tags and Default Tags got deprecated.
            In RF 7.0 Force Tags and Default Tags got removed.

            This method works fine with RF 7.0.
            """
            self.setting_table.test_tags.extend(node.values)

        def visit_TestTags(self, node):
            """
            Since RF 5.1 Test Tag is and alias for Force Tags.
            """
            self.setting_table.test_tags.extend(node.values)

        def visit_DefaultTags(self, node):
            """
            In RF 6.0 Force Tags and Default Tags got deprecated.
            In RF 7.0 Force Tags and Default Tags got removed.
            """
            self.setting_table.default_tags = node.values

        def visit_TestCase(self, node):
            tc = TestCase()
            tc.name = node.name
            tags = [
                statement.values
                for statement in node.body
                if hasattr(statement, "type") and statement.type == "TAGS"
            ]
            tc.tags = list(flatten(tags))
            self.testcase_table.append(tc)


def _exclude_messages(kws):
    return [kw for kw in kws if not isinstance(kw, Message)]


def get_keywords(node):
    if ROBOT_VERSION >= (5, 0):
        kws = list(node.body)
        if getattr(node, 'has_teardown', False):
            kws.append(node.teardown)
        kws = _exclude_messages(kws)
    else:
        kws = node.keywords
    return kws


def get_all_keywords(test):
    """
    all keywords, including setup and teardown
    """
    if ROBOT_VERSION >= (5, 0):
        kws = list(test.body)
        if getattr(test, 'has_setup', False):
            kws.append(test.setup)
        if getattr(test, 'has_teardown', False):
            kws.append(test.teardown)
        kws = _exclude_messages(kws)
    else:
        kws = test.keywords.all
    return kws


def get_test_setup_keyword(test):
    """
    Get Test Setup Keyword
    :param test: instance of test
    :return: test setup keyword
    """
    return _get_setup_or_teardown_keyword(test, "setup")


def get_test_teardown_keyword(test):
    """
    Get Test Teardown Keyword
    :param test: instance of test
    :return: test teardown keyword
    """
    return _get_setup_or_teardown_keyword(test, "teardown")


def get_suite_setup_keyword(suite):
    """
    Get Suite Setup Keyword
    :param suite: instance of suite
    :return: suite setup keyword
    """
    return _get_setup_or_teardown_keyword(suite, "setup")


def get_suite_teardown_keyword(suite):
    """
    Get Suite Teardown Keyword
    :param suite: instance of suite
    :return: suite teardown keyword
    """
    return _get_setup_or_teardown_keyword(suite, "teardown")


def _get_setup_or_teardown_keyword(suite_or_test, phase):
    """
    `phase` is a string: 'setup' or 'teardown'
    """
    if ROBOT_VERSION >= (5, 0):
        kw = getattr(suite_or_test, phase, None)
    else:
        kw = getattr(suite_or_test.keywords, phase, None)
    return kw


def get_suite_setup_and_teardown_keywords(suite):
    """

    :param suite:
    :return: return suite setup and teardown keywords if defined
    """

    suite_keywords = [
        kw
        for kw in (get_suite_setup_keyword(suite), get_suite_teardown_keyword(suite))
        if kw
    ]
    return suite_keywords


def get_messages(node):
    """
    Earlier result side Keyword had messages and keywords separately, but nowadays also messages are stored in body
    along with executed keywords as well as FOR and IF objects. The old messages is preserved as a property
    getting messages from body.
    """
    try:
        msgs = node.messages
    except AttributeError:
        msgs = []
    return msgs


__all__ = [
    "ROBOT_VERSION",
    "SETUP_OR_TEARDOWN_KW_TYPES",
    "TestData",
    "TestCase",
    "get_keywords",
    "get_all_keywords",
    "get_test_setup_keyword",
    "get_test_teardown_keyword",
    "get_suite_setup_keyword",
    "get_suite_teardown_keyword",
    "get_suite_setup_and_teardown_keywords",
    "get_messages",
]
